# Exact cover tiling search with rectangle pieces; symmetry break for repeated 0 and 1 squares.
from collections import defaultdict
H,W=hole.shape
piece_specs=[('8',4,1),('0',1,1),('0',1,1),('0',1,1),('0',1,1),('45',7,2),('6',3,2),('1',2,2),('9',2,4),('1',2,2),('5',8,2),('26',7,3),('4',7,2),('81',6,5)]
# unique cell index
coords=list(map(tuple,np.argwhere(hole))); idx={p:i for i,p in enumerate(coords)}
placements=[]
for pi,(name,hh,ww) in enumerate(piece_specs):
    dims={(hh,ww),(ww,hh)}
    for ph,pw in dims:
        for r in range(H-ph+1):
            for c in range(W-pw+1):
                cells=[]; valid=True
                for rr in range(r,r+ph):
                    for cc in range(c,c+pw):
                        if not hole[rr,cc]: valid=False;break
                        cells.append(idx[(rr,cc)])
                    if not valid:break
                if valid:
                    bit=sum(1<<i for i in cells)
                    placements.append((pi,bit,r,c,ph,pw))
bycell=defaultdict(list)
for p in placements:
    for i in range(len(coords)):
        if p[1]>>i&1: bycell[i].append(p)
print('placements',len(placements), 'per piece',[sum(p[0]==i for p in placements) for i in range(len(piece_specs))])

# Rebuild placements only original orientations (no rotate) and enumerate limited solutions/count
fixed=[]
for pi,(name,hh,ww) in enumerate(piece_specs):
    for r in range(H-hh+1):
        for c in range(W-ww+1):
            if hole[r:r+hh,c:c+ww].all():
                cells=[idx[(rr,cc)] for rr in range(r,r+hh) for cc in range(c,c+ww)]
                bit=sum(1<<i for i in cells)
                fixed.append((pi,bit,r,c,hh,ww))
bycellf=defaultdict(list)
for p in fixed:
    for i in range(len(coords)):
        if p[1]>>i&1:bycellf[i].append(p)
print([sum(p[0]==i for p in fixed) for i in range(len(piece_specs))])

